      function rendreSetsIdleV25_(j){
        const actifs=
          j &&
          j.sets &&
          Array.isArray(
            j.sets.actifs
          )
            ?j.sets.actifs
            :[];

        if(!actifs.length){
          return `
            <div class="soreal-idle-set-v25">
              🧩 Aucun bonus de set actif.
              Équipe plusieurs pièces portant le même nom de set.
            </div>
          `;
        }

        return actifs
          .map(function(s){
            return `
              <div class="soreal-idle-set-v25">
                🧩 <strong>${idleHtml_(s.nom)}</strong>
                · ${idleEntier_(s.pieces)}/${idleEntier_(s.piecesMax||6)} pièces
                · <strong>+${idleEntier_(s.bonusPourcent)} % puissance</strong>
                ${
                  s.description
                    ?'<div style="margin-top:4px;opacity:.75">'+
                      idleHtml_(s.description)+
                      '</div>'
                    :''
                }
              </div>
            `;
          })
          .join('');
      }

      let idleForgeActionV25=false;

      function forgerEquipementIdleV25_(
        slot
      ){
        if(
          !SOREAL_SESSION ||
          !idleEtat ||
          !idleEtat.equipement
        ){
          return;
        }

        const objet=
          idleEtat.equipement[
            slot
          ];

        if(!objet){
          messageFlottantIdleV32_(
            '❌ Aucun objet équipé.'
          );
          return;
        }

        const forgeEtat=
          idleEtat.forge &&
          idleEtat.forge[slot]
            ?idleEtat.forge[slot]
            :null;

        const cout=
          Math.max(
            1,
            idleEntier_(
              forgeEtat&&forgeEtat.cout
            )
          );

        if(
          idleEntier_(
            idleEtat.materiaux
          )<cout
        ){
          messageFlottantIdleV32_(
            '❌ Pas assez de matériaux.'
          );
          return;
        }

        idleEtat.materiaux=
          Math.max(
            0,
            idleEntier_(
              idleEtat.materiaux
            )-
            cout
          );

        const avant=
          idleNombre_(
            objet.bonusPuissance
          );

        objet.forge=
          idleEntier_(
            objet.forge
          )+1;

        objet.bonusPuissance=
          Math.max(
            1,
            Math.round(
              avant*1.18+1
            )
          );

        if(
          Array.isArray(
            idleEtat.inventaire
          )
        ){
          const indexInventaire=
            idleEtat.inventaire.findIndex(
              function(item){
                return String(
                  item&&item.id||''
                )===
                String(
                  objet.id||''
                );
              }
            );

          if(indexInventaire>=0){
            idleEtat.inventaire[
              indexInventaire
            ]=
              objet;
          }
        }

        const delta=
          idleNombre_(
            objet.bonusPuissance
          )-
          avant;

        idleEtat.puissance=
          Math.max(
            1,
            idleNombre_(
              idleEtat.puissance
            )+
            delta
          );

        idleEtat.bonusEquipement=
          Math.max(
            0,
            idleNombre_(
              idleEtat.bonusEquipement
            )+
            delta
          );

        if(!idleEtat.forge){
          idleEtat.forge={};
        }

        const meta=
          idleEtat.forgeMeta||{
            base:5,
            croissance:1.65
          };

        idleEtat.forge[slot]={
          niveau:
            idleEntier_(
              objet.forge
            ),
          cout:
            Math.max(
              1,
              Math.round(
                idleNombre_(
                  meta.base
                )*
                Math.pow(
                  Math.max(
                    1,
                    idleNombre_(
                      meta.croissance
                    )
                  ),
                  idleEntier_(
                    objet.forge
                  )
                )
              )
            )
        };

        planifierRenduOptimisteIdleV60_();

        ajouterActionRapideIdleV60_(
          'forge',
          slot
        );

        messageFlottantIdleV32_(
          '🔥 Forge +'+
          idleEntier_(
            objet.forge
          )
        );
      }


      function agrandirSacIdleV25_(){
        if(
          !SOREAL_SESSION ||
          !idleEtat
        ){
          return;
        }

        const cout=
          Math.max(
            1,
            idleEntier_(
              idleEtat
                .coutExtensionInventaire
            )
          );

        if(
          idleEntier_(
            idleEtat.materiaux
          )<cout
        ){
          messageFlottantIdleV32_(
            '❌ Pas assez de matériaux.'
          );
          return;
        }

        const meta=
          idleEtat.inventaireMeta||{
            base:18,
            pas:6,
            coutBase:25,
            croissance:1.85,
            max:90
          };

        if(
          idleEntier_(
            idleEtat.inventaireCapacite
          )>=
          idleEntier_(
            meta.max
          )
        ){
          messageFlottantIdleV32_(
            '❌ Capacité maximale.'
          );
          return;
        }

        idleEtat.materiaux=
          Math.max(
            0,
            idleEntier_(
              idleEtat.materiaux
            )-
            cout
          );

        idleEtat.inventaireCapacite=
          Math.min(
            idleEntier_(
              meta.max
            ),
            idleEntier_(
              idleEtat.inventaireCapacite
            )+
            idleEntier_(
              meta.pas
            )
          );

        idleEtat.inventaireLibre=
          Math.max(
            0,
            idleEntier_(
              idleEtat.inventaireCapacite
            )-
            idleEntier_(
              idleEtat.inventaireUtilise
            )
          );

        const extensions=
          Math.max(
            0,
            Math.floor(
              (
                idleEntier_(
                  idleEtat.inventaireCapacite
                )-
                idleEntier_(
                  meta.base
                )
              )/
              Math.max(
                1,
                idleEntier_(
                  meta.pas
                )
              )
            )
          );

        idleEtat.coutExtensionInventaire=
          Math.max(
            1,
            Math.round(
              idleNombre_(
                meta.coutBase
              )*
              Math.pow(
                Math.max(
                  1,
                  idleNombre_(
                    meta.croissance
                  )
                ),
                extensions
              )
            )
          );

        planifierRenduOptimisteIdleV60_();

        ajouterActionRapideIdleV60_(
          'bag',
          1
        );
      }


      window.__forgerEquipementIdleV25__=forgerEquipementIdleV25_;
      window.__agrandirSacIdleV25__=agrandirSacIdleV25_;


