      function afficherBulleIdleV76_(id,texte){
        const el=
          document.getElementById(id);

        if(!el)return;

        el.textContent=
          String(texte||'');

        el.classList.remove('visible');

        requestAnimationFrame(function(){
          el.classList.add('visible');
        });

        setTimeout(function(){
          el.classList.remove('visible');
        },2700);
      }


      function choisirPhraseIdleV76_(liste){
        const valeurs=
          Array.isArray(liste)
            ?liste
            :[];

        if(!valeurs.length){
          return '';
        }

        return valeurs[
          Math.floor(
            Math.random()*valeurs.length
          )
        ];
      }


      function demarrerBullesCombatIdleV76_(j){
        if(idleDialogueTimerV76){
          clearInterval(idleDialogueTimerV76);
          idleDialogueTimerV76=null;
        }

        if(!j||!j.combatBossActif){
          return;
        }

        /*
         * Correctif 2026-09-18 (Norman, en direct : "supprime les messages
         * des anciens boss Soreal") — phrasesBossIdleV76_ (taunts 100%
         * inventés SOREAL, ex. "Je vais te mettre en palette.", jamais
         * sourcés wiki) retirée avec sa bulle dédiée
         * (sorealIdleDialogueBossV76) : la vraie histoire du boss
         * (histoireBossMarkupIdleV142_, sourcée wiki, sous la barre de vie)
         * remplace ce rôle. Seule la bulle du joueur reste.
         */
        const faireParler=function(){
          if(
            !idleEtat ||
            !idleEtat.combatBossActif
          ){
            return;
          }

          afficherBulleIdleV76_(
            'sorealIdleDialogueJoueurV76',
            choisirPhraseIdleV76_(
              phrasesJoueurIdleV76_()
            )
          );
        };

        setTimeout(faireParler,850);

        idleDialogueTimerV76=
          setInterval(
            faireParler,
            5200
          );
      }


