/*
 * Audit 2026-09-16 : ITOPOD retombait sur le rendu générique
 * (Niveau/temporaire/permanent, "Level 0") faute d'être spécial-cassé
 * dans pageSystemeMetaIdleV130_ — même défaut que Perks/Quirks/Challenges
 * avant leurs propres pages dédiées. Le serveur (advanceLateSystems,
 * idle-ngu-progression.js) suit déjà étage/kills/PPP réels (wiki ITOPOD :
 * "every 10 enemies killed advances 1 floor", "(200+Floor) PPP/kill",
 * "1 000 000 PPP = 1 PP") — il ne manquait qu'un affichage dédié.
 */
function pageItopodIdleV1_(j){
        const s=systemeMetaParIdIdleV130_(j,'tower');
        if(!s||!s.state||!s.state.unlocked)return entetePageIdleV28_('🏢 ITOPOD','Infinite Tower of Pissed-Off Dudes — grimpe les étages, gagne des PP.')+'<div class="soreal-idle-section-v8" style="text-align:center;padding:26px">🔒 Système verrouillé.</div>';
        const d=(s.state.data)||{};
        const etage=idleEntier_(d.floor);
        const kills=idleEntier_(d.kills);
        const versProchainEtage=kills%10;
        const ppProgress=Math.max(0,idleNombre_(d.ppProgress));
        const pp=idleEntier_((j&&j.systemes&&j.systemes.currencies&&j.systemes.currencies.pp)||0);
        const actif=Boolean(s.state.active);
        return entetePageIdleV28_(
          '🏢 ITOPOD',
          'Infinite Tower of Pissed-Off Dudes — chaque 10 ennemis vaincus fait monter d’un étage ; (200 + Étage) PPP par kill, 1 000 000 PPP = 1 PP.'
        )+
        '<div class="soreal-idle-summary-grid-v28">'+
          '<div class="soreal-idle-summary-v28">Étage<b>'+etage+'</b></div>'+
          '<div class="soreal-idle-summary-v28">PP disponibles<b>'+pp+'</b></div>'+
        '</div>'+
        '<div class="soreal-idle-section-v8">'+
          '<div class="soreal-idle-window-title-v31">📊 Progression</div>'+
          '<div class="soreal-idle-note-v4">'+
            '🗡️ Ennemis vaincus (total) : <b>'+formatGrandNombreIdleV70_(kills)+'</b>'+
          '</div>'+
          '<div class="soreal-idle-note-v4" style="margin-top:5px">'+
            '⬆️ Vers le prochain étage : <b>'+versProchainEtage+' / 10</b>'+
          '</div>'+
          '<div class="soreal-idle-note-v4" style="margin-top:5px">'+
            '🔷 Progression PP : <b>'+formatGrandNombreIdleV70_(ppProgress)+' / 1 000 000</b>'+
          '</div>'+
          '<div style="display:flex;gap:7px;flex-wrap:wrap;margin-top:9px">'+
            '<button type="button" class="soreal-idle-expand-button-v25" onclick="window.__toggleSystemeMetaIdleV130__(\'tower\')">'+
              (actif?'⏸️ Désactiver':'▶️ Activer')+
            '</button>'+
          '</div>'+
        '</div>';
      }

